def peek(self, default=_marker):
    try:
        peeked = next(self)
    except StopIteration:
        if default is _marker:
            raise
        return default
    if self._index is None:
        self._index = len(self._cache)
    self._index -= 1
    self._cache.insert(self._index, peeked)  # Reset the iterator's position
    return peeked
